class Solution:
    def differByOne(self, dict: List[str]) -> bool:
        n = len(dict)
        for i in range(n):
            for j in range(i + 1, n):
                diff = 0
                for a, b in zip(dict[i], dict[j]):
                    if a != b:
                        diff += 1
                        if diff > 1:
                            break
                if diff == 1:
                    return True
        return False

