class Solution {
public:
    bool differByOne(vector<string>& dict) {
        int n = dict.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int diff = 0;
                for (int k = 0; k < (int)dict[i].size(); ++k) {
                    if (dict[i][k] != dict[j][k] && ++diff > 1) break;
                }
                if (diff == 1) return true;
            }
        }
        return false;
    }
};

