class Solution {
public:
    bool differByOne(vector<string>& dict) {
        unordered_set<string> seen;
        for (string w : dict) {
            for (int i = 0; i < (int)w.size(); ++i) {
                char old = w[i];
                w[i] = '*';
                if (!seen.insert(w).second) return true;
                w[i] = old;
            }
        }
        return false;
    }
};

