class Solution {
public:
    bool differByOne(vector<string>& d) {
        const long long M1 = 1000000007LL, M2 = 998244353LL, B = 131LL;
        auto mul = [](long long a, long long b, long long mod) {
            return (__int128)a * b % mod;
        };
        int m = d[0].size();
        vector<long long> p1(m + 1, 1), p2(m + 1, 1);
        for (int i = 0; i < m; ++i) {
            p1[i + 1] = mul(p1[i], B, M1);
            p2[i + 1] = mul(p2[i], B, M2);
        }
        unordered_set<long long> seen;
        for (auto& w : d) {
            vector<long long> a1(m + 1, 0), a2(m + 1, 0), s1(m + 1, 0), s2(m + 1, 0);
            for (int i = 0; i < m; ++i) {
                long long c = w[i];
                a1[i + 1] = (mul(a1[i], B, M1) + c) % M1;
                a2[i + 1] = (mul(a2[i], B, M2) + c) % M2;
            }
            for (int i = m - 1; i >= 0; --i) {
                long long c = w[i];
                s1[i] = (mul(c, p1[m - 1 - i], M1) + s1[i + 1]) % M1;
                s2[i] = (mul(c, p2[m - 1 - i], M2) + s2[i + 1]) % M2;
            }
            for (int i = 0; i < m; ++i) {
                long long h1 = (mul(a1[i], p1[m - i], M1) + s1[i + 1]) % M1;
                long long h2 = (mul(a2[i], p2[m - i], M2) + s2[i + 1]) % M2;
                if (!seen.insert(h1 * M2 + h2).second) return true;
            }
        }
        return false;
    }
};

