class Solution {
    public boolean differByOne(String[] d) {
        final long M1 = 1000000007L, M2 = 998244353L, B = 131L;
        int m = d[0].length();
        long[] p1 = new long[m + 1], p2 = new long[m + 1];
        p1[0] = p2[0] = 1;
        for (int i = 0; i < m; i++) {
            p1[i + 1] = p1[i] * B % M1;
            p2[i + 1] = p2[i] * B % M2;
        }
        Set<Long> seen = new HashSet<>();
        for (String w : d) {
            long[] a1 = new long[m + 1], a2 = new long[m + 1];
            long[] s1 = new long[m + 1], s2 = new long[m + 1];
            for (int i = 0; i < m; i++) {
                long c = w.charAt(i);
                a1[i + 1] = (a1[i] * B + c) % M1;
                a2[i + 1] = (a2[i] * B + c) % M2;
            }
            for (int i = m - 1; i >= 0; i--) {
                long c = w.charAt(i);
                s1[i] = (c * p1[m - 1 - i] + s1[i + 1]) % M1;
                s2[i] = (c * p2[m - 1 - i] + s2[i + 1]) % M2;
            }
            for (int i = 0; i < m; i++) {
                long h1 = (a1[i] * p1[m - i] + s1[i + 1]) % M1;
                long h2 = (a2[i] * p2[m - i] + s2[i + 1]) % M2;
                if (!seen.add(h1 * M2 + h2)) return true;
            }
        }
        return false;
    }
}

