    const seen = new Set();
    for (const w of d) {
        const a1 = Array(m + 1).fill(0n), a2 = Array(m + 1).fill(0n);
        const s1 = Array(m + 1).fill(0n), s2 = Array(m + 1).fill(0n);
        for (let i = 0; i < m; i++) {
            const c = BigInt(w.charCodeAt(i));
            a1[i + 1] = (a1[i] * B + c) % M1;
            a2[i + 1] = (a2[i] * B + c) % M2;
